import { cn } from '@/react/lib/cn'

// The hairline (console2.css .v2-menu-sep, .v2-rows) as its own part: 1px in the edge colour, across or down.
// `inset` is the menu's: 4px of air above and below, running out to the panel's edges through its 4px padding.
// Decorative by default; pass `semantic` when it separates content a screen reader should hear as split.
export interface SeparatorProps { orientation?: 'horizontal' | 'vertical', inset?: boolean, semantic?: boolean, className?: string }

export function Separator({ orientation = 'horizontal', inset, semantic, className }: SeparatorProps) {
  return (
    <div
      data-ds="separator"
      role={semantic ? 'separator' : 'none'}
      aria-orientation={semantic ? orientation : undefined}
      className={cn('shrink-0 bg-edge', [orientation === 'vertical' ? 'w-px self-stretch' : 'h-px w-full', inset && (orientation === 'vertical' ? '-my-1 mx-1' : '-mx-1 my-1 w-auto')], className)}
    />
  )
}

export default Separator

// Joins class names, skipping falsy ones: cn('a', on && 'b', ['c', undefined]). It does not merge conflicting
// utilities (no tailwind-merge), as Vue's class binding does not: the library's classes are written not to compete,
// and a className from the caller is appended after them, as Vue appends a fallthrough class.
export type ClassValue = string | false | null | undefined | 0 | ClassValue[]

export function cn(...values: ClassValue[]): string {
	const out: string[] = []
	for (const v of values) {
		if (!v) continue
		if (Array.isArray(v)) {
			const s = cn(...v)
			if (s) out.push(s)
		}
		else out.push(v)
	}
	return out.join(' ')
}

import { type PropertyValues } from 'lit'
import { DsElement, define } from '@/elements/lib/element'
import styles from 'virtual:tw'

// Separator.vue as <conare-separator>: the hairline (console2.css .v2-menu-sep, .v2-rows) as its own part: 1px in the
// edge colour, across or down. `inset` is the menu's: 4px of air above and below, running out to the panel's edges
// through its 4px padding. Decorative by default; pass `semantic` when it separates content a screen reader should hear
// as split. The host is the hairline (Vue's root div), so a class on the element (my-3) lands on it.

/** @summary The hairline, across or down. */
export class Separator extends DsElement {
	static styles = [DsElement.styles, styles]
	static properties = { orientation: { reflect: true }, inset: { type: Boolean, reflect: true }, semantic: { type: Boolean } }

	orientation: 'horizontal' | 'vertical' = 'horizontal'
	inset = false
	semantic = false

	protected updated(changed: PropertyValues) {
		super.updated(changed)
		this.setAttribute('role', this.semantic ? 'separator' : 'none')
		if (this.semantic) this.setAttribute('aria-orientation', this.orientation)
		else this.removeAttribute('aria-orientation')
	}

	render() {
		return null
	}
}

define('separator', Separator)

/* Separator.vue's classes on the host (the Vue root div): across by default, down with orientation="vertical", and the
   menu's inset. A class on the element wins over these, as a class on <Separator> does. */
:host { @apply block shrink-0 bg-edge h-px w-full; }
:host([orientation="vertical"]) { @apply h-auto w-px self-stretch; }
:host([inset]:not([orientation="vertical"])) { margin: 4px -4px !important; }
:host([inset][orientation="vertical"]) { margin: -4px 4px !important; }
/* The inset's margins are !important: the page's preflight (margin: 0) wins over a plain :host rule. Vue's w-auto
   loses to its w-full in the stylesheet's order, so the rule keeps the full width, as Vue renders it. */
